$vmRel='src\SmartLedger.App\ViewModels\InventoryViewModel.cs'
$vmPath=Join-Path $root $vmRel
$vm=[IO.File]::ReadAllText($vmPath,[Text.Encoding]::UTF8)
if($vm -notmatch 'SelectProductBatchViewCommand'){
 $anchor='    [RelayCommand]' + [Environment]::NewLine + '    private void OpenEdit(Product? product)'
 if(-not $vm.Contains($anchor)){ $anchor='    [RelayCommand]' + [char]10 + '    private void OpenEdit(Product? product)' }
 if(-not $vm.Contains($anchor)){throw 'OpenEdit insertion point not found'}
 $insert='    [RelayCommand]' + [char]10 + '    private void SelectProductBatchView(Product? product)' + [char]10 + '    {' + [char]10 + '        if (product is null) return;' + [char]10 + '        SelectedProduct = product;' + [char]10 + '    }' + [char]10 + [char]10
 $vm=$vm.Replace($anchor,$insert+$anchor)
 [IO.File]::WriteAllText($vmPath,$vm,[Text.UTF8Encoding]::new($false))
 $changes.Add("$vmRel :: batch drawer selection command")
}
Write-Output 'PHASE2_UI_EDITS_APPLIED'
$changes | ForEach-Object { Write-Output $_ }
